def installed_state(payload, target, catalog, prepared):
    family, version = prepared['targetType'], prepared['firmwareVersion']
    summaries = inventory_rows(payload, target, family)
    evidence = {'state': 'unknown', 'checkedComponents': 0, 'requestedVersion': version}
    if family == 'Domain':
        elements = target['networkElements']
        versions = [e.get('Version') if version_text(e.get('Version')) else None for e in elements]
        evidence['switchVersions'] = [{'Moid': e['Moid'], 'version': v} for e, v in zip(elements, versions)]
        if any(version_text(v) and v != version for v in versions):
            evidence.update(state='needed', reason='At least one Fabric Interconnect runs a different firmware version.')
            return evidence
        if not all(version_text(v) and v == version for v in versions):
            evidence['reason'] = 'Running firmware version is missing for one or both Fabric Interconnects.'
            return evidence
        if any(e.get('PeerFirmwareOutOfSync') is True or (e.get('PeerFirmwareOutOfSync') is not None and type(e['PeerFirmwareOutOfSync']) is not bool) for e in elements):
            evidence['reason'] = 'The Fabric Interconnect pair reports firmware out of sync.'
            return evidence
        if not prepared.get('enablePsuUpgrade') and not prepared.get('enablePdbFpgaUpgrade'):
            evidence.update(state='installed', reason='Both validated Fabric Interconnects already run the requested version.')
            return evidence
        if len(summaries) != 2:
            evidence['reason'] = 'The requested auxiliary upgrades need component inventory for both Fabric Interconnects.'
            return evidence
        anchors = {'NXOS'}
        if prepared.get('enablePsuUpgrade'):
            anchors.add('PSU')
        if prepared.get('enablePdbFpgaUpgrade'):
            anchors.add('BoardController')
        state, reason, checked = components_state(list(summaries.values()), catalog, anchors)
    else:
        current = target.get('installedBundleVersion') if version_text(target.get('installedBundleVersion')) else None
        summary = summaries.get(target['targetMoid'])
        summary_version = summary.get('BundleVersion') if summary and version_text(summary.get('BundleVersion')) else None
        evidence.update(inventoryBundleVersion=current, summaryBundleVersion=summary_version)
        versions = [v for v in (current, summary_version) if version_text(v)]
        if version in versions and any(v != version for v in versions):
            evidence['reason'] = 'The target bundle and component summary report contradictory installed versions.'
            return evidence
        if versions and all(v != version for v in versions):
            evidence.update(state='needed', reason='Current bundle inventory identifies a different installed version.')
            return evidence
        if not summary or version not in versions:
            evidence['reason'] = 'A matching installed bundle and its complete component inventory are unavailable.'
            return evidence
        # Advanced atomic callers retain their exclusion contract, but a full
        # component no-op must never hide a partial-scope request.
        if prepared.get('excludedComponents') not in (None, [], ['none']) or prepared.get('excludedComponentPids'):
            evidence['reason'] = 'A partial component scope cannot be classified as a full-bundle no-op.'
            return evidence
        anchors, topology = ({'CIMC', 'BIOS'}, []) if family == 'Server' else ({'PSU'}, [])
        if family == 'UCS-X Chassis' and target.get('xfmTopology', {}).get('healthyPair'):
            topology = [('UCSX-FS-9516', 2)]
        state, reason, checked = components_state([summary], catalog, anchors, topology)
    evidence.update(state=state, reason=reason, checkedComponents=checked)
    return evidence


