            matches = relation(item.get('Chassis'), target['targetMoid'], 'equipment.Chassis')
        else:
            refs = item.get('NetworkElements')
            expected = {e['Moid'] for e in target['networkElements']}
            matches = (isinstance(refs, list) and len(refs) == 2 and all(isinstance(r, dict)
                and relation(r, r.get('Moid'), 'network.Element') for r in refs)
                and {r['Moid'] for r in refs} == expected)
        if not matches:
            raise ValueError('Existing firmware upgrade does not match the exact validated target relationships.')
