def inspect_preflight(active_payload, target, prepared, inventory_payload, catalog, inventory_status='200', inventory_succeeded='true'):
    family = prepared['targetType']
    expected_type = UPGRADE_TYPES[family]
    result = {'targetType': family, 'targetMoid': target['targetMoid'], 'imageMoid': catalog['imageMoid'],
              'firmwareVersion': prepared['firmwareVersion'], 'activeResources': [],
              'bestEffortIdempotencyGuard': True, 'duplicateRaceRemains': True,
              'requestAccepted': False, 'newRequestSubmitted': False, 'completed': False}
    code, state, message, error = '502', 'invalid', 'Firmware preflight response is invalid', ''
    upgrade_id = resource_type = status_id = ''
    try:
        active = active_resources(active_payload, target, family)
        result['activeResources'] = active
        if len(active) > 1:
            code, error = '409', 'Multiple potentially active upgrades match the target. Inspect Intersight before submitting another request.'
        elif active:
            existing = active[0]
            upgrade_id, resource_type, status_id = existing['Moid'], expected_type, existing['upgradeStatusMoid'] or ''
            result.update(createdMoid=upgrade_id, createdObjectType=resource_type, upgradeStatusMoid=status_id or None,
                          resourceReused=True, noOp=True, requestedImageMatches=(existing['imageMoid'] == catalog['imageMoid']) if existing['imageMoid'] else None)
            if existing['Status'] == 'NONE':
                code, error = '409', 'An existing upgrade has an unpopulated status. Inspect its status in Intersight before retrying; no new request was submitted.'
            else:
                code, state = '200', 'handled'
                result.update(status='already-in-progress', goalSatisfied=False)
                message = 'A firmware upgrade is already in progress; no new request was submitted.'
                if existing['imageMoid'] and existing['imageMoid'] != catalog['imageMoid']:
                    message += ' The existing upgrade targets a different image.'
                if status_id:
                    message += ' Monitor progress in Intersight. Upgrade Status ID: ' + status_id + '.'
                else:
                    message += ' Monitor progress in Intersight. Upgrade ID: ' + upgrade_id + '; Upgrade Resource Type: ' + resource_type + '.'
        else:
            if str(inventory_status) != '200' or inventory_succeeded != 'true':
                result['inventoryHttpStatus'] = str(inventory_status)
                evidence = {'state': 'unknown', 'reason': 'Installed firmware inventory is unavailable.', 'checkedComponents': 0}
            else:
                if isinstance(inventory_payload, str):
                    try:
                        inventory_payload = json.loads(inventory_payload)
                    except ValueError:
                        inventory_payload = None
                if inventory_payload is None:
                    evidence = {'state': 'unknown', 'reason': 'Installed firmware inventory could not be read.', 'checkedComponents': 0}
                else:
                    evidence = installed_state(inventory_payload, target, catalog, prepared)
            result['installedFirmwareEvidence'] = evidence
            if evidence['state'] == 'installed':
                code, state = '200', 'handled'
                result.update(status='already-installed', noOp=True, completed=True, goalSatisfied=True, installedStateVerified=True)
                message = 'The requested firmware is already installed for the validated upgrade scope; no new request was submitted.'
            elif evidence['state'] == 'needed':
                code, state = '200', 'clear'
                message = 'No active upgrade was found; the requested firmware upgrade can be submitted.'
            else:
                code, state = '200', 'clear'
                result['installedStateVerified'] = False
                result['inventoryWarning'] = evidence['reason']
                message = 'Installed firmware could not be verified; continue with the requested upgrade.'
    except (ValueError, TypeError, KeyError) as exc:
        error = str(exc)
    if state == 'invalid':
        result['status'] = 'inspection-required' if code == '409' else 'invalid'
        message = error or message
        error = message
    elif state == 'clear':
        result['status'] = 'clear'
    result['message'] = message
    return {'preflightStatus': state, 'preflightMessage': message, 'preflightStatusCode': code,
            'preflightErrorMessage': error, 'preflightResultJson': json.dumps(result, separators=(',', ':')),
            'createdMoid': upgrade_id, 'createdResourceType': resource_type, 'upgradeStatusMoid': status_id,
            'helperReady': True}


