    result['newRequestSubmitted'] = True
    result['reconciliation'] = {'attempted': True, 'httpStatus': recovery_http, 'matched': False}
    eligible = status_code in (400, 408, 409, 412, 499) or status_code is None or status_code == 200 or status_code < 400 or status_code >= 500
